const ICONS: Record<string, (props: IconProps) => React.JSX.Element> = {
    LinkedIn: LinkedinIcon,
    GitHub: GithubIcon,
    Instagram: InstagramIcon,
    YouTube: YoutubeIcon,
    Behance: BehanceIcon,
};

type Props = { size?: number; className?: string };

export default function ContactIcons({ size = 20, className = "" }: Props) {
    return (
        <div className={`flex items-center gap-4 ${className}`}>
            {contacts.map((c) => {
                const Icon = ICONS[c.label] ?? LinkedinIcon;
                return (
                    <a
                        key={c.label}
                        href={c.href}
                        target="_blank"
                        rel="noopener noreferrer"
                        aria-label={c.label}
                        className="text-current transition-colors hover:text-accent"
                    >
                        <Icon size={size} />
                    </a>
                );
            })}
        </div>
    );
}